NotaApprofondimento computazionale: tradurre la ricorsione in Stan





Il programma seguente applica la stessa coppia di parametri a tutte le traiettorie, condiziona sul primo obiettivo di ciascun partecipante e calcola ricorsivamente lo stato previsto.

Mostra/Nascondi codicestan_code_goal_sample &lt;- "
data {
  int&lt;lower=1&gt; Ntotal;
  int&lt;lower=1&gt; Nsubj;
  array[Ntotal] int&lt;lower=1, upper=Nsubj&gt; subject;
  array[Ntotal] int&lt;lower=1&gt; trial;
  vector[Ntotal] goal;
  vector[Ntotal] performance;
}

parameters {
  real alpha_logit;
  real beta;
  real&lt;lower=0&gt; sigma;
}

transformed parameters {
  real&lt;lower=0, upper=1&gt; alpha = inv_logit(alpha_logit);
  vector[Ntotal] mu;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      mu[i] = goal[i];
    } else {
      mu[i] = mu[i - 1]
              + alpha * (performance[i - 1] - mu[i - 1])
              + beta;
    }
  }
}

model {
  alpha_logit ~ normal(0, 1);
  beta ~ normal(0, 0.25);
  sigma ~ normal(0, 0.75);

  for (i in 1:Ntotal) {
    if (trial[i] &gt; 1) {
      goal[i] ~ normal(mu[i], sigma);
    }
  }
}

generated quantities {
  vector[Ntotal] y_rep;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      y_rep[i] = goal[i];
    } else {
      y_rep[i] = normal_rng(mu[i], sigma);
    }
  }
}
"



