Introduciamo quindi il modello rivale. La regola di apprendimento rimane la stessa; ciò che cambia è il modello di scelta, nel quale la differenza tra i valori appresi e la risposta precedente contribuiscono separatamente alla probabilità della scelta corrente.






NotaApprofondimento computazionale: modello rivale con perseverazione






Mostra/Nascondi codicestancode_rw_perseveration &lt;- "
data {
  int&lt;lower=1&gt; T;
  array[T] int&lt;lower=0, upper=1&gt; choice;
  array[T] int&lt;lower=0, upper=1&gt; reward;
  array[T] int&lt;lower=0, upper=1&gt; rich_is_A;
  real&lt;lower=0.5, upper=1&gt; p_reward_rich;
}

parameters {
  real alpha_raw;
  real log_tau;
  real kappa;
}

transformed parameters {
  real&lt;lower=0, upper=1&gt; alpha = inv_logit(alpha_raw);
  real&lt;lower=0&gt; tau = exp(log_tau);
}

model {
  vector[2] q = rep_vector(0.5, 2);

  alpha_raw ~ normal(logit(0.20), 1);
  log_tau ~ normal(log(2), 0.6);
  kappa ~ normal(0, 1);

  for (t in 1:T) {
    int a = choice[t] + 1;
    real previous_signed =
      t == 1 ? 0 : 2 * choice[t - 1] - 1;
    real eta =
      tau * (q[2] - q[1]) +
      kappa * previous_signed;

    choice[t] ~ bernoulli_logit(eta);
    q[a] += alpha * (reward[t] - q[a]);
  }
}

generated quantities {
  array[T] int choice_rep;
  array[T] int reward_rep;
  vector[T] log_lik;

  {
    vector[2] q_obs = rep_vector(0.5, 2);
    vector[2] q_rep = rep_vector(0.5, 2);
    int previous_rep_signed = 0;

    for (t in 1:T) {
      int a_obs;
      int a_rep;
      int chosen_is_rich;
      real previous_obs_signed;
      real eta_obs;
      real eta_rep;
      real reward_probability;

      previous_obs_signed =
        t == 1 ? 0 : 2 * choice[t - 1] - 1;

      eta_obs =
        tau * (q_obs[2] - q_obs[1]) +
        kappa * previous_obs_signed;

      log_lik[t] = bernoulli_logit_lpmf(
        choice[t] | eta_obs
      );

      a_obs = choice[t] + 1;
      q_obs[a_obs] += alpha *
        (reward[t] - q_obs[a_obs]);

      eta_rep =
        tau * (q_rep[2] - q_rep[1]) +
        kappa * previous_rep_signed;

      choice_rep[t] =
        bernoulli_logit_rng(eta_rep);
      a_rep = choice_rep[t] + 1;

      chosen_is_rich =
        (
          (choice_rep[t] == 0 &&
           rich_is_A[t] == 1) ||
          (choice_rep[t] == 1 &&
           rich_is_A[t] == 0)
        ) ? 1 : 0;

      reward_probability =
        chosen_is_rich == 1
        ? p_reward_rich
        : 1 - p_reward_rich;

      reward_rep[t] =
        bernoulli_rng(reward_probability);

      q_rep[a_rep] += alpha *
        (reward_rep[t] - q_rep[a_rep]);

      previous_rep_signed =
        2 * choice_rep[t] - 1;
    }
  }
}
"



