41.7.2 Implementazione e stima
Il programma seguente realizza il modello. Per comprendere il capitolo, non è necessario seguire ogni istruzione, ma è sufficiente riconoscere la corrispondenza tra le distribuzioni della popolazione, i parametri individuali, la dinamica e il modello osservazionale.






NotaApprofondimento computazionale: modello gerarchico in Stan






Mostra/Nascondi codicestan_code_goal_hierarchical &lt;- "
data {
  int&lt;lower=1&gt; Ntotal;
  int&lt;lower=1&gt; Nsubj;
  array[Ntotal] int&lt;lower=1, upper=Nsubj&gt; subject;
  array[Ntotal] int&lt;lower=1&gt; trial;
  vector[Ntotal] goal;
  vector[Ntotal] performance;
}

parameters {
  real mu_alpha_logit;
  real&lt;lower=0&gt; tau_alpha_logit;
  vector[Nsubj] z_alpha;

  real mu_beta;
  real&lt;lower=0&gt; tau_beta;
  vector[Nsubj] z_beta;

  real&lt;lower=0&gt; sigma;
}

transformed parameters {
  vector[Nsubj] alpha_logit =
    mu_alpha_logit + tau_alpha_logit * z_alpha;
  vector&lt;lower=0, upper=1&gt;[Nsubj] alpha = inv_logit(alpha_logit);
  vector[Nsubj] beta = mu_beta + tau_beta * z_beta;
  vector[Ntotal] mu;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      mu[i] = goal[i];
    } else {
      int s = subject[i];
      mu[i] = mu[i - 1]
              + alpha[s] * (performance[i - 1] - mu[i - 1])
              + beta[s];
    }
  }
}

model {
  mu_alpha_logit ~ normal(0, 1);
  tau_alpha_logit ~ normal(0, 0.75);
  z_alpha ~ std_normal();

  mu_beta ~ normal(0, 0.25);
  tau_beta ~ normal(0, 0.25);
  z_beta ~ std_normal();

  sigma ~ normal(0, 0.75);

  for (i in 1:Ntotal) {
    if (trial[i] &gt; 1) {
      goal[i] ~ normal(mu[i], sigma);
    }
  }
}

generated quantities {
  real&lt;lower=0, upper=1&gt; alpha_typical = inv_logit(mu_alpha_logit);
  vector[Ntotal] y_rep;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      y_rep[i] = goal[i];
    } else {
      y_rep[i] = normal_rng(mu[i], sigma);
    }
  }
}
"



